package org.companion.sharetest;
import android.app.Activity;import android.os.Bundle;import android.content.Intent;import android.content.ClipData;import android.net.Uri;import android.widget.*;
public class ShareActivity extends Activity{
  @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(40,80,40,40);root.setBackgroundColor(0xfff4f2ec);TextView title=new TextView(this);title.setText("A sample reading app · QA fixture");title.setTextSize(24);root.addView(title);TextView post=new TextView(this);post.setText("COMPANION_E2E_SHARED_POST\nA synthetic article, with a link and an image. Only this source content is simulated; Android sharing and capture are real.\nhttps://example.com/companion-e2e");post.setTextSize(18);post.setPadding(0,40,0,40);root.addView(post);add(root,"Share text and link",false);add(root,"Share image",true);setContentView(root);}
  private void add(LinearLayout root,String label,boolean image){Button b=new Button(this);b.setText(label);root.addView(b);b.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_SEND);i.setType(image?"image/png":"text/plain");i.putExtra(Intent.EXTRA_TEXT,image?"COMPANION_E2E_SHARED_IMAGE":"COMPANION_E2E_SHARED_LINK https://example.com/companion-e2e");if(image){Uri u=Uri.parse("content://org.companion.sharetest.images/sample.png");i.putExtra(Intent.EXTRA_STREAM,u);i.setClipData(ClipData.newRawUri("sample",u));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);}startActivity(Intent.createChooser(i,"Share test material"));});}
}
